from urllib.parse import quote


# Official signature assets are kept on the authenticated backend side instead of
# being published as anonymous frontend static files. They are only returned in
# a print payload after the corresponding approval stage is APPROVED.
_SIGNATURES = {
    "STORE": {
        "name": "Baihaqi Ahmad",
        "label": "Store",
        "svg": '''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 102 90"><image width="102" height="90" href="data:image/png;base64,"/></svg>''',
    },
    "CHEF": {
        "name": "Edi Susanto",
        "label": "Head Chef",
        "svg": '''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 102 90"><image width="102" height="90" href="data:image/png;base64,"/></svg>''',
    },
    "AREA_MANAGER": {
        "name": "Doni Idriadhi",
        "label": "Area Manager",
        "svg": '''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 145 90"><image width="145" height="90" href="data:image/png;base64,"/></svg>''',
    },
}


def _signature_key(step: dict) -> str | None:
    text = f"{step.get('name') or ''} {step.get('approver_role') or ''}".upper()
    if "STORE" in text:
        return "STORE"
    if "CHEF" in text:
        return "CHEF"
    if "AREA MANAGER" in text or "CAMP BOSS" in text or "PM/CAMP" in text or "PM CAMP" in text:
        return "AREA_MANAGER"
    return None


def add_private_print_signatures(payload: dict) -> dict:
    """Attach Batam signature data only to approved print approval records."""
    if "BATAM" not in str(payload.get("location_name") or "").upper():
        return payload

    for step in payload.get("approval_history") or []:
        if str(step.get("status") or "").upper() != "APPROVED":
            continue
        key = _signature_key(step)
        asset = _SIGNATURES.get(key) if key else None
        if not asset:
            continue
        step["signature_name"] = asset["name"]
        step["signature_label"] = asset["label"]
        step["signature_image"] = "data:image/svg+xml;charset=utf-8," + quote(asset["svg"], safe="")
    return payload
